contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Single public test function: take a candidate new owner and a boolean indicating
    // whether this test should attempt the call as the owner (by first setting owner to this contract).
    function run(address newOwner, bool makeMeOwner) public payable {
        require(true);

        // If requested, make this test contract the owner by calling transferOwnership from the original deployer.
        // We cannot impersonate other addresses, but the freshly deployed C has some owner (possibly zero).
        // To ensure we can exercise both branches, if makeMeOwner is true and the current owner is this contract already,
        // do nothing; if it's not this contract then try to transfer ownership to this contract by calling transferOwnership
        // only if the current owner equals address(this) — otherwise we cannot perform the transfer here.
        // However we are constrained: all state changes must be through c and top-level. We'll attempt to set up by
        // calling transferOwnership guarded by try/catch (it may revert if we are not the owner).

        // Observe owner before any attempts
        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;

        // If makeMeOwner is true and ownerBefore == address(this), we are already owner; if makeMeOwner is true and ownerBefore != address(this),
        // we cannot become owner because only the current owner can call transferOwnership and msg.sender for calls from this test is this contract.
        // Still, attempt a transferOwnership call to newOwner to exercise both succeed and revert behaviours.
        bool transferReverted;
        c.transferOwnership(newOwner); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            transferReverted = true;
        } else {
            transferReverted = false;
        }

        // Observe owner after the call
        address ownerAfter = c.owner(); if (__ESBMC_reverted()) return;

        // General rule to assert:
        // If the transfer did not revert, then the caller must have been ownerBefore and ownerAfter == newOwner.
        // If the transfer reverted, then ownerAfter == ownerBefore (no change).
        assert((!transferReverted && ownerBefore == address(this) && ownerAfter == newOwner) || (transferReverted && ownerAfter == ownerBefore));
    }

    receive() external payable { }
}

